	 ('Каково главное назначение кластерного анализа?','Разбиение множества объектов на однородные группы','["Нахождение функциональной зависимости между переменными", "Разбиение множества объектов на однородные группы", "Прогнозирование временных рядов", "Определение весов признаков экспертами"]',2),
	 ('От какого английского слова происходит название «кластерный анализ» и что оно означает?','Cluster - гроздь, скопление','["Class - класс, категория", "Clear - чистый, ясный", "Cluster - гроздь, скопление", "Clast - часть, фрагмент"]',2),
	 ('К какому разделу математических методов относится кластерный анализ?','К методам многомерного анализа','["К методам одномерного анализа", "К методам многомерного анализа", "К методам линейного программирования", "К теории графов"]',2),
	 ('Из скольких основных шагов состоит типичное исследование с использованием кластерного анализа?','Пять','["Три", "Пять", "Семь", "Десять"]',2),
	 ('В каком случае математическая функция расстояния между двумя объектами будет равна нулю?','Только тогда, когда объекты полностью совпадают','["Когда объекты максимально отдалены друг от друга", "Только тогда, когда объекты полностью совпадают", "Когда стандартизованный Z-вклад равен нулю", "Когда мера их сходства минимальна"]',3),
	 ('Какая функция расстояния является наиболее популярной и часто используемой?','Евклидово расстояние','["Степенное расстояние", "Сюпремум-норма", "Манхэттенское расстояние", "Евклидово расстояние"]',3),
	 ('В каких пределах находится коэффициент меры сходства для двух несовпадающих объектов?','От 0 (включительно) до 1 (не включительно)','["От -1 до 1", "От 0 (включительно) до 1 (не включительно)", "От 1 до бесконечности", "Строго равен 0"]',3),
	 ('На какие две глобальные группы делятся все алгоритмы кластерного анализа?','Иерархические и неиерархические','["Параллельные и перпендикулярные", "Иерархические и неиерархические", "Линейные и нелинейные", "Статические и динамические"]',4),
	 ('Что показывает Z-вклад?','Сколько стандартных отклонений отделяет наблюдение от среднего значения','["Процент несогласия между экспертами", "Сумму всех значений в кластере", "Сколько стандартных отклонений отделяет наблюдение от среднего значения", "Длину вектора в евклидовом пространстве"]',3),
	 ('Как называется график, визуализирующий результаты процесса последовательной иерархической кластеризации?','Дендограмма','["Гистограмма", "Диаграмма рассеяния", "Дендограмма", "Круговая диаграмма"]',4);
INSERT INTO public.api_question (text,correct_answer,"options",test_id) VALUES
	 ('В каком методе целевой функцией для объединения выступает внутригрупповая сумма квадратов отклонений?','Метод Ворда','["Метод ближнего соседа", "Центроидный метод", "Метод дальнего соседа", "Метод Ворда"]',4),
	 ('В чем заключается главное достоинство кластерного анализа?','Он позволяет классифицировать объекты по целому набору признаков одновременно','["Он дает абсолютно точные предсказания будущего", "Он позволяет классифицировать объекты по целому набору признаков одновременно", "Он не требует наличия исходных данных", "Он работает только с бинарными значениями"]',2),
	 ('Какой метод лежит в основе построения строгой решеточной таксономии алгоритмов?','Формальный Анализ Понятий (ФАП)','["Формальный Анализ Понятий (ФАП)", "Метод главных компонент (PCA)", "Анализ Фурье", "Метод опорных векторов (SVM)"]',6),
	 ('Как называется математическое соответствие, которое задают операторы взятия штриха между частично упорядоченными множествами объектов и признаков?','Соответствие Галуа','["Соответствие Ньютона", "Соответствие Пифагора", "Соответствие Галуа", "Соответствие Эйлера"]',8),
	 ('Как вычисляется расстояние между группами в центроидном методе?','Как расстояние между центрами (средними значениями) этих кластеров','["Как расстояние между самыми удаленными точками кластеров", "Как расстояние между центрами (средними значениями) этих кластеров", "Как сумма всех расстояний между точками", "Как минимальное расстояние между любыми двумя объектами"]',4),
	 ('Как называется процесс перевода вещественных непрерывных данных в бинарный или категориальный вид для использования алгоритмами вроде BiMax?','Дискретизация и шкалирование','["Интерполяция и экстраполяция", "Дискретизация и шкалирование", "Интегрирование и дифференцирование", "Нормализация и стандартизация"]',5),
	 ('Что представляет собой бикластер с постоянными значениями?','Подмножество строк и столбцов, все элементы на пересечении которых равны одной константе','["Бикластер, в котором значения возрастают в геометрической прогрессии", "Подмножество строк и столбцов, все элементы на пересечении которых равны одной константе", "Бикластер, в котором значения меняются только по строкам", "Бикластер, содержащий только нулевые значения"]',5),
	 ('В каких моделях рассматриваются бикластеры с когерентными (согласованными) значениями?','В аддитивной и мультипликативной моделях','["В аддитивной и мультипликативной моделях", "В статической и динамической моделях", "В квантовой и релятивистской моделях", "В бинарной и логической моделях"]',5),
	 ('Какой тип данных использует алгоритм BiMax, разработанный для анализа генетической информации?','Исключительно бинарные данные (0/1)','["Только комплексные числа", "Текстовые строки", "Исключительно бинарные данные (0/1)", "Действительные числа с плавающей точкой"]',5),
	 ('В чем заключается особенность работы классического алгоритма Ченга и Черча?','Он находит один бикластер за проход, требуя маскировки для поиска следующего','["Он находит все возможные бикластеры за одну миллисекунду", "Он находит один бикластер за проход, требуя маскировки для поиска следующего", "Он работает только с текстовыми документами", "Он делит матрицу строго пополам на каждом шаге"]',6);
INSERT INTO public.api_question (text,correct_answer,"options",test_id) VALUES
	 ('Какой алгоритмической стратегии из нижеперечисленных НЕ существует в стандартной классификации алгоритмов бикластеризации?','Стратегия квантового запутывания','["Жадная стратегия итеративного поиска", "Стратегия «разделяй и властвуй»", "Стратегия квантового запутывания", "Полное перечисление бикластеров"]',6),
	 ('Какая структура получается, если бикластеры вообще не имеют пересечений ни по строкам, ни по столбцам, но заполняют матрицу?','Структура шахматной доски','["Иерархическое перекрытие", "Структура шахматной доски", "Произвольно расположенные бикластеры", "Когерентное дерево"]',5),
	 ('Почему при классификации алгоритмов бикластеризации решеточная таксономия считается более удобной, чем строгая древовидная?','Она позволяет алгоритму-подклассу наследовать свойства сразу от нескольких надклассов','["Она выглядит красивее при печати", "Она позволяет алгоритму-подклассу наследовать свойства сразу от нескольких надклассов", "Она требует меньше оперативной памяти", "Она удаляет все алгоритмы, использующие жадный поиск"]',6),
	 ('Для чего применяется нормирование исходных данных?','Чтобы устранить неоднородность единиц измерения различных признаков','["Чтобы устранить неоднородность единиц измерения различных признаков", "Чтобы удалить все нулевые значения из выборки", "Чтобы искусственно увеличить количество кластеров", "Чтобы перевести текст в числовой формат"]',3),
	 ('Какой важный дополнительный признак рекомендуется вводить в таксономию алгоритмов для их более точного разделения?','Тип исходных значений (например, 0/1 данные или вещественные числа)','["Язык программирования, на котором написан алгоритм", "Тип исходных значений (например, 0/1 данные или вещественные числа)", "Имя создателя алгоритма", "Год публикации алгоритма"]',6),
	 ('К какому классу стратегий относится поиск, при котором на каждом шаге принимается локально оптимальное решение без гарантии нахождения глобального оптимума?','Жадная стратегия','["Определение параметров распределения", "Жадная стратегия", "Полное перечисление", "Комбинация строк и столбцов"]',6),
	 ('Из каких двух множеств строго состоит математически определенное «формальное понятие» в ФАП?','Из объема и содержания','["Из причины и следствия", "Из объема и содержания", "Из функции и аргумента", "Из вектора и матрицы"]',7),
	 ('Какие три свойства делают бинарное отношение «отношением частичного порядка»?','Рефлексивность, антисимметричность, транзитивность','["Коммутативность, ассоциативность, дистрибутивность", "Рефлексивность, антисимметричность, транзитивность", "Инъективность, сюръективность, биективность", "Непрерывность, дифференцируемость, интегрируемость"]',7),
	 ('Что такое точная верхняя грань (супремум) для множества элементов?','Наименьшая из всех верхних граней этого множества','["Наибольший из всех возможных элементов во вселенной", "Наименьшая из всех верхних граней этого множества", "Сумма всех элементов множества", "Элемент, который строго меньше всех элементов множества"]',7),
	 ('Какое частично упорядоченное множество называется «решёткой»?','То, в котором для любых двух элементов всегда существуют точная верхняя и точная нижняя грани','["То, в котором нет ни одного связанного элемента", "То, в котором для любых двух элементов всегда существуют точная верхняя и точная нижняя грани", "То, в котором количество элементов всегда четное", "То, которое можно нарисовать только в виде квадрата"]',7);
INSERT INTO public.api_question (text,correct_answer,"options",test_id) VALUES
	 ('Что означает свойство «антисимметричности» бинарного отношения <=?','Если x <= y и y <= x, то x = y','["Если x <= y и y <= z, то x <= z", "Если x <= y и y <= x, то x = y", "Для любого x всегда выполняется x <= x", "Если x <= y, то x всегда строго меньше y"]',7),
	 ('Какое из перечисленных свойств структуры бикластеров выгодно отличает бикластеризацию от традиционных методов жесткой кластеризации?','Способность находить перекрывающиеся бикластеры (пересечения по строкам и столбцам)','["Способность находить только изолированные, неперекрывающиеся блоки", "Обязательное условие формирования структуры шахматной доски", "Способность находить перекрывающиеся бикластеры (пересечения по строкам и столбцам)", "Способность работать только с квадратными матрицами"]',5),
	 ('Что представляет собой формальный контекст в математическом смысле?','Тройку из множества объектов, множества признаков и отношения между ними','["Тройку из множества объектов, множества признаков и отношения между ними", "График, показывающий зависимость объектов от времени", "Таблицу, содержащую только вещественные числа", "Алгоритм поиска кратчайшего пути в графе"]',8),
	 ('Как интерпретируется запись "g I m" в рамках формального контекста?','Объект g обладает признаком m','["Объект g строго больше признака m", "Объект g обладает признаком m", "Объект g не имеет ничего общего с m", "Признак m порождает объект g"]',8),
	 ('Что вернет штрих-оператор (A''), если применить его к некоторому множеству объектов A?','Множество всех признаков, общих для всех объектов из множества A','["Множество всех признаков, общих для всех объектов из множества A", "Случайный набор признаков из базы данных", "Количество объектов в множестве A", "Множество объектов, у которых нет ни одного признака"]',8),
	 ('Какое свойство оператора замыкания означает, что его повторное применение к уже замкнутому множеству не изменит результат?','Идемпотентность','["Изотонность", "Идемпотентность", "Экстенсивность", "Антисимметричность"]',8),
	 ('В каком случае множество объектов считается «замкнутым»?','Если двойное применение штрих-оператора возвращает само это множество','["Если оно не содержит ни одного объекта", "Если двойное применение штрих-оператора возвращает само это множество", "Если оно включает в себя абсолютно все признаки контекста", "Если в нем находится ровно один объект"]',8),
	 ('Из каких двух элементов состоит формальное понятие в ФАП?','Из объема и содержания','["Из функции и ее аргумента", "Из объема и содержания", "Из причины и следствия", "Из числителя и знаменателя"]',9),
	 ('Какое строгое математическое условие должно выполняться для пары множеств (A, B), чтобы она являлась формальным понятием?','Штрих от A должен равняться B, и одновременно штрих от B должен равняться A','["Множество A должно быть равно множеству B", "Штрих от A должен равняться B, и одновременно штрих от B должен равняться A", "Сумма элементов A и B должна равняться нулю", "Множества A и B не должны иметь общих элементов"]',9),
	 ('Какими множествами всегда являются объем и содержание любого формального понятия?','Замкнутыми множествами','["Открытыми множествами", "Замкнутыми множествами", "Пустыми множествами", "Бесконечными множествами"]',9);
INSERT INTO public.api_question (text,correct_answer,"options",test_id) VALUES
	 ('Какую математическую структуру образует множество всех возможных формальных понятий одного контекста?','Решетку Галуа','["Многомерную матрицу", "Решетку Галуа", "Линейный массив", "Несвязный граф"]',9),
	 ('Как называется формальный контекст, который является одновременно строчно- и столбцево-редуцированным?','Редуцированный контекст','["Избыточный контекст", "Редуцированный контекст", "Масштабированный контекст", "Бинарный контекст"]',9),
	 ('Что означает импликация X -> Y на множествах признаков в формальном контексте?','Все объекты, обладающие признаками из множества X, также обладают признаками из множества Y','["Все объекты, обладающие признаками из множества X, также обладают признаками из множества Y", "Признаки X и Y никогда не встречаются у одного и того же объекта", "Объекты с признаком Y всегда встречаются чаще", "Признак X является причиной появления признака Y"]',10),
	 ('Сколько базовых элементов (множеств и отношений) содержит математическая структура многозначного формального контекста?','Четыре (объекты, признаки, значения и тернарное отношение)','["Два (объекты и признаки)", "Три (объекты, признаки и бинарное отношение)", "Четыре (объекты, признаки, значения и тернарное отношение)", "Пять (добавляется множество исключений)"]',10),
	 ('Как называется процедура преобразования сложного многозначного формального контекста в однозначный (бинарный) контекст?','Шкалирование','["Итерация", "Шкалирование", "Дифференцирование", "Редукция"]',10),
	 ('Как называется однозначный контекст, который получается на выходе после завершения процедуры шкалирования?','Производный контекст','["Абсолютный контекст", "Производный контекст", "Нулевой контекст", "Векторный контекст"]',10),
	 ('Какой тип шкалирования следует применить для обработки признака, значения которого невозможно упорядочить или сравнить между собой?','Номинальное шкалирование','["Порядковое шкалирование", "Логарифмическое шкалирование", "Номинальное шкалирование", "Дробное шкалирование"]',10),
	 ('Каким правилам подчиняются импликации формального контекста?','Аксиомам Армстронга','["Аксиомам Армстронга", "Законам Кеплера", "Постулатам Бора", "Аксиомам Евклида"]',10),
	 ('При каком условии первое формальное понятие считается менее общим, чем второе?','Если объем первого понятия является подмножеством объема второго','["Если объем первого понятия является подмножеством объема второго", "Если первое понятие было найдено раньше второго", "Если содержание первого понятия меньше содержания второго", "Если их объемы полностью совпадают"]',9),
	 ('Как называется диаграмма, с помощью которой графически изображаются конечные частично упорядоченные множества?','Диаграмма Хассе','["Диаграмма Венна", "Диаграмма Ганта", "Диаграмма Хассе", "Дерево Пифагора"]',7);
INSERT INTO public.api_question (text,correct_answer,"options",test_id) VALUES
	 ('Какова логика работы агломеративных иерархических методов на стартовом шаге?','Каждый отдельный объект принимается за самостоятельный кластер','["Все объекты случайным образом разбиваются на 2 кластера", "Все объекты сразу объединяются в один гигантский кластер", "Каждый отдельный объект принимается за самостоятельный кластер", "Исключаются все объекты с отрицательными значениями"]',4);

